const METHODS = {
  GET:     { safe: true,  idempotent: true,  desc: '读取资源' },
  HEAD:    { safe: true,  idempotent: true,  desc: '只取头部（探测存在性）' },
  OPTIONS: { safe: true,  idempotent: true,  desc: '询问支持的方法（CORS 预检）' },
  POST:    { safe: false, idempotent: false, desc: '创建子资源 / 非幂等操作' },
  PUT:     { safe: false, idempotent: true,  desc: '整体替换指定资源' },
  PATCH:   { safe: false, idempotent: false, desc: '局部修改（语义上不保证幂等）' },
  DELETE:  { safe: false, idempotent: true,  desc: '删除指定资源' },
};

console.log('方法  | 安全 | 幂等 | 超时可直接重试 | 语义');
console.log('------+------+------+----------------+--------------------------------');
for (const [m, v] of Object.entries(METHODS)) {
  console.log(
    m.padEnd(6) + '| ' + (v.safe ? ' 是  ' : ' 否  ') + ' | ' + (v.idempotent ? ' 是  ' : ' 否  ') +
    ' | ' + (v.idempotent ? '    可以       ' : '   不可以      ') + ' | ' + v.desc
  );
}
console.log('');
console.log('推论一：网络超时时，GET / PUT / DELETE 可直接重试；POST 必须靠「幂等键」去重。');
console.log('推论二：GET 会被浏览器预取、爬虫遍历、缓存代理自动触发 —— 绝不能在 GET 上做写操作。');
console.log('推论三：PUT 会整体替换资源，没传的字段可能被清空 —— 只改一个字段应使用 PATCH。');
